from pathlib import Path
import base64
import html
import tempfile
import streamlit as st
import streamlit.components.v1 as components

# A Little Gift From Sweetheart
# Self-contained build: compressed WebP assets are embedded in this file.
TITLE_BG = ""
ROOM_BG = ""
BATHROOM_BG = ""
MEE_MEO = ""
DANG_KHOA = ""

def image_uri(data):
    return f"data:image/webp;base64,{data}"

# The custom drag-and-shave component must be deployed beside app.py.
SHAVE_COMPONENT_DIR = Path(__file__).resolve().parent / "shave_component"
if not (SHAVE_COMPONENT_DIR / "index.html").is_file():
    st.error(
        "Thiếu thư mục shave_component/index.html. "
        "Hãy tải toàn bộ thư mục shave_component lên GitHub, đặt cùng cấp với app.py."
    )
    st.stop()
shave_drag_game = components.declare_component(
    "shave_drag_game",
    path=str(SHAVE_COMPONENT_DIR),
)

# Self-contained wash component: recreate its HTML in /tmp when the GitHub
# repository does not contain wash_component/index.html. This prevents the
# missing-folder error and means app.py can launch the wash mini-game by itself.
WASH_COMPONENT_HTML_B64 = ""
WASH_COMPONENT_DIR = Path(tempfile.gettempdir()) / "a_little_gift_wash_component"
WASH_COMPONENT_DIR.mkdir(parents=True, exist_ok=True)
WASH_COMPONENT_INDEX = WASH_COMPONENT_DIR / "index.html"
try:
    current_html = WASH_COMPONENT_INDEX.read_bytes() if WASH_COMPONENT_INDEX.exists() else b""
except OSError:
    current_html = b""
expected_html = base64.b64decode(WASH_COMPONENT_HTML_B64)
if current_html != expected_html:
    WASH_COMPONENT_INDEX.write_bytes(expected_html)

wash_face_game = components.declare_component(
    "wash_face_game",
    path=str(WASH_COMPONENT_DIR),
)

# Air Blade mini-game component, shown after the preparation/wash sequence.
GAME_COMPONENT_DIR = Path(__file__).resolve().parent / "ride_game_component"
if not (GAME_COMPONENT_DIR / "index.html").is_file():
    st.error("Thiếu thư mục ride_game_component. Hãy giữ thư mục này cùng cấp với app.py.")
    st.stop()
ride_game = components.declare_component(
    "ride_game",
    path=str(GAME_COMPONENT_DIR),
)

# Automatic restaurant date scene shown immediately after the riding game is won.
DATE_COMPONENT_DIR = Path(__file__).resolve().parent / "restaurant_date_component"
if not (DATE_COMPONENT_DIR / "index.html").is_file():
    st.error("Thiếu thư mục restaurant_date_component. Hãy giữ thư mục này cùng cấp với app.py.")
    st.stop()
restaurant_date = components.declare_component(
    "restaurant_date",
    path=str(DATE_COMPONENT_DIR),
)


st.set_page_config(
    page_title="A Little Gift From Sweetheart",
    page_icon="🌸",
    layout="wide",
    initial_sidebar_state="collapsed",
)

def start_game():
    st.session_state.scene = "room"
    st.session_state.chat_open = False
    st.session_state.reply = None
    st.session_state.completed_tasks = set()
    st.session_state.active_task = None
    st.session_state.shaved_hairs = set()

if "scene" not in st.session_state:
    st.session_state.scene = "title"
if "chat_open" not in st.session_state:
    st.session_state.chat_open = False
if "reply" not in st.session_state:
    st.session_state.reply = None
if "completed_tasks" not in st.session_state:
    st.session_state.completed_tasks = set()
else:
    st.session_state.completed_tasks = set(st.session_state.completed_tasks) & {"shave", "wash"}
if "active_task" not in st.session_state:
    st.session_state.active_task = None
if "shaved_hairs" not in st.session_state:
    st.session_state.shaved_hairs = set()

st.markdown("""
<style>
/* Mobile orientation gate: block the entire app until the phone is landscape. */
@media screen and (max-width: 900px) and (orientation: portrait) {
  html, body, .stApp { overflow: hidden !important; }
  .stApp::before {
    content: "HÃY XOAY NGANG ĐIỆN THOẠI\\A\\A📱  Xoay màn hình 90° sang trái hoặc phải\\A\\A1. Mở Trung tâm điều khiển / Cài đặt nhanh.\\A2. Bật Tự động xoay (Auto-rotate).\\A3. Xoay điện thoại nằm ngang để bắt đầu.\\A\\A♡ Game sẽ tự mở khi màn hình đã nằm ngang.";
    white-space: pre-line;
    position: fixed !important; inset: 0 !important; z-index: 2147483647 !important;
    display: flex !important; align-items: center !important; justify-content: center !important;
    padding: 28px 24px !important; text-align: center !important;
    color: #fff1e8 !important; background: radial-gradient(circle at 50% 20%, #69465f, #211a2c 72%) !important;
    font: 700 clamp(15px, 4.3vw, 21px)/1.8 Arial, sans-serif !important;
    text-shadow: 2px 2px #211a2c !important;
    border: 8px solid #b98291 !important; box-sizing: border-box !important;
    pointer-events: auto !important;
  }
}

/* Landscape-phone layout: mirror the desktop composition without mobile stacking. */
@media screen and (orientation: landscape) and (max-height: 520px) and (pointer: coarse) {
  html, body, .stApp, [data-testid="stAppViewContainer"],
  [data-testid="stMain"], [data-testid="stMainBlockContainer"] {
    width:100vw !important; min-width:0 !important; height:100svh !important;
    min-height:0 !important; overflow:hidden !important;
  }
  [data-testid="stMainBlockContainer"] {
    padding:0 !important; margin:0 !important; max-width:none !important;
  }
  [data-testid="stVerticalBlock"] { gap:0 !important; }
  [data-testid="stElementContainer"] { margin:0 !important; }
  .stButton { width:auto !important; }
  .stButton > button { min-height:38px !important; padding:6px 14px !important; font-size:clamp(12px,2.2vh,16px) !important; }
  iframe[title="ride_game"], iframe[title="restaurant_date"],
  iframe[title="wash_face_game"], iframe[title="shave_drag_game"] {
    display:block !important; width:100vw !important; height:100svh !important;
    min-height:100svh !important; max-height:100svh !important;
    border:0 !important; margin:0 !important;
  }
  .room-page, .bathroom-page, .title-background { width:100vw !important; height:100svh !important; }
}

</style>
""", unsafe_allow_html=True)

if st.session_state.scene == "title":
    with st.container(key="title_screen"):
        st.markdown(
            f'<div class="title-background"><img src="{image_uri(TITLE_BG)}" alt="A Little Gift From Sweetheart — Saigon riverside"></div>',
            unsafe_allow_html=True
        )
        if st.button("START", key="start_game"):
            start_game()
            st.rerun()
elif st.session_state.scene == "room":
    notice = "" if st.session_state.chat_open else """
        <div class="phone-notification">
          <div class="notification-head">TIN NHẮN MỚI · MẸ MEO</div>
          <div class="notification-message">em chuẩn bị xong rùi, anh qua rước em nhóoo</div>
        </div>"""

    st.markdown(f"""
    <div class="room-page">
      <div class="room-frame">
        <img class="room-background" src="{image_uri(ROOM_BG)}" alt="Phòng ngủ pixel art">
        <div class="room-tint"></div>
        <div class="room-title">PHÒNG CỦA ĐĂNG KHOA</div>
        <img class="khoa-sprite" src="{image_uri(DANG_KHOA)}" alt="Đăng Khoa">
        {notice}
      </div>
    </div>
    """, unsafe_allow_html=True)

    if not st.session_state.chat_open:
        st.markdown('<div class="hint">ĐIỆN THOẠI CỦA ĐĂNG KHOA RUNG LÊN...</div>', unsafe_allow_html=True)
        if st.button("📱  MỞ TIN NHẮN", key="open_chat"):
            st.session_state.chat_open = True
            st.rerun()
    else:
        reply = st.session_state.reply
        conversation = f"""
          <div class="chat-message player-row">
            <div class="chat-bubble player">{html.escape(reply)}</div>
          </div>
          <div class="chat-message">
            <img class="chat-avatar" src="{image_uri(MEE_MEO)}" alt="Mẹ Meo">
            <div class="chat-bubble">dạaaa</div>
          </div>
          <div class="chat-caption">MẸ MEO ĐÃ NHẮN LẠI ♡</div>
        """ if reply is not None else ""

        st.markdown(f"""
        <div class="chat-panel">
          <div class="chat-header">MẸ MEO <span style="float:right;font-size:11px">ĐANG HOẠT ĐỘNG</span></div>
          <div class="chat-message">
            <img class="chat-avatar" src="{image_uri(MEE_MEO)}" alt="Mẹ Meo">
            <div class="chat-bubble">em chuẩn bị xong rùi, anh qua rước em nhóoo</div>
          </div>
          {conversation}
        </div>
        """, unsafe_allow_html=True)

        if reply is None:
            st.markdown('<div class="chat-caption">ĐĂNG KHOA NÊN TRẢ LỜI THẾ NÀO?</div>', unsafe_allow_html=True)
            choices = [
                "okeyy, anh qua liền",
                "em đợi xíu nhé, anh đang quaa",
                "anh sắp tới rồi",
                "kê anh đi đâyy",
            ]
            for i, choice in enumerate(choices):
                if st.button(choice, key=f"reply_{i}", use_container_width=True):
                    st.session_state.reply = choice
                    st.rerun()
        else:
            st.markdown('<div class="prepare-hint">MẸ MEO ĐÃ SẴN SÀNG — ĐẾN LƯỢT ĐĂNG KHOA CHUẨN BỊ RỒI!</div>', unsafe_allow_html=True)
            if st.button("🧴  CHUẨN BỊ", key="prepare", use_container_width=True):
                st.session_state.scene = "bathroom"
                st.rerun()
else:
    if st.session_state.scene == "bathroom" and st.session_state.active_task == "wash":
        st.markdown("""
        <style>
          html, body, .stApp, [data-testid="stAppViewContainer"], [data-testid="stMain"], [data-testid="stMainBlockContainer"] {background:transparent!important}
          [data-testid="stMainBlockContainer"] {padding:0!important;margin:0!important;max-width:100%!important}
          [data-testid="stVerticalBlock"] {gap:0!important}
          [data-testid="stElementContainer"] {margin:0!important}
          iframe[title="wash_face_game"] {display:block!important;width:100%!important;border:0!important;margin:0!important}
        </style>
        """, unsafe_allow_html=True)
        result = wash_face_game(key="wash_face_surface", default=None)
        if result == "done":
            st.session_state.completed_tasks.add("wash")
            st.session_state.active_task = None
            st.rerun()
    elif st.session_state.scene == "bathroom" and st.session_state.active_task == "shave":
        # Full-viewport mini-game: remove Streamlit's default page spacing/background
        # so no purple strip appears before the embedded shaving component.
        st.markdown("""
        <style>
          html, body, .stApp, [data-testid="stAppViewContainer"],
          [data-testid="stMain"], [data-testid="stMainBlockContainer"] {
            background: transparent !important;
          }
          [data-testid="stMainBlockContainer"] {
            padding: 0 !important;
            margin: 0 !important;
            max-width: 100% !important;
          }
          [data-testid="stVerticalBlock"] { gap: 0 !important; }
          [data-testid="stElementContainer"] { margin: 0 !important; }
          iframe[title="shave_drag_game"] {
            display: block !important;
            width: 100% !important;
            border: 0 !important;
            margin: 0 !important;
          }
        </style>
        """, unsafe_allow_html=True)
        result = shave_drag_game(key="shave_drag_surface", default=None)
        if result == "done":
            st.session_state.completed_tasks.add("shave")
            st.session_state.active_task = None
            st.session_state.shaved_hairs = set(range(7))
            st.rerun()
    elif st.session_state.scene == "bathroom":
        st.markdown(f"""
        <div class="bathroom-page">
          <div class="bathroom-frame">
            <img class="bathroom-background" src="{image_uri(BATHROOM_BG)}" alt="Nhà tắm pixel art">
            <div class="bathroom-title">NHÀ TẮM CỦA ĐĂNG KHOA</div>
          </div>
        </div>
        """, unsafe_allow_html=True)
        st.markdown('<div class="task-instruction">ĐĂNG KHOA CẦN HOÀN THÀNH 2 VIỆC TRƯỚC KHI RA NGOÀI</div>', unsafe_allow_html=True)

        tasks = [("shave", "🪒  CẠO RÂU"), ("wash", "💧  RỬA MẶT")]
        completed = st.session_state.completed_tasks
        st.markdown(f'<div class="task-status">ĐÃ HOÀN THÀNH: {len(completed)}/2</div>', unsafe_allow_html=True)
        for task_id, label in tasks:
            done = task_id in completed
            button_label = f"✓  {label.replace('🪒  ', '').replace('💧  ', '').replace('👕  ', '')} — ĐÃ XONG" if done else label
            if st.button(button_label, key=f"task_{task_id}", use_container_width=True, disabled=done):
                st.session_state.active_task = task_id
                if task_id == "shave":
                    st.session_state.shaved_hairs = set()
                st.rerun()

        if len(completed) == 2:
            st.markdown('<div class="task-instruction">ĐÃ CHUẨN BỊ XONG! ĐĂNG KHOA SẴN SÀNG RỒI ♡</div>', unsafe_allow_html=True)
            if st.button("TIẾP TỤC  →", key="bathroom_continue", use_container_width=True):
                st.session_state.scene = "game"
                st.rerun()
    elif st.session_state.scene == "game":
        st.markdown("""
        <style>
          html, body, .stApp, [data-testid="stAppViewContainer"],
          [data-testid="stMain"], [data-testid="stMainBlockContainer"] {
            background: #241d2b !important;
          }
          [data-testid="stMainBlockContainer"] {
            padding: 0 !important; margin: 0 !important; max-width: 100% !important;
          }
          [data-testid="stVerticalBlock"] { gap: 0 !important; }
          [data-testid="stElementContainer"] { margin: 0 !important; }
          iframe[title="ride_game"] {
            display: block !important; width: 100% !important;
            min-height: 100vh !important; border: 0 !important; margin: 0 !important;
          }
        </style>
        """, unsafe_allow_html=True)
        game_result = ride_game(key="ride_game_surface", height=760, scrolling=False, default=None)
        # Component value is sent only when the player presses the victory Continue button.
        # Accept the normal scalar value and mapping-shaped values for compatibility.
        game_won = (
            game_result == "won"
            or (isinstance(game_result, dict) and game_result.get("value") == "won")
        )
        if game_won:
            st.session_state.scene = "restaurant_date"
            st.rerun()
    elif st.session_state.scene == "restaurant_date":
        st.markdown("""
        <style>
          html, body, .stApp, [data-testid="stAppViewContainer"],
          [data-testid="stMain"], [data-testid="stMainBlockContainer"] {
            background: #241d2b !important;
          }
          [data-testid="stMainBlockContainer"] {
            padding: 0 !important; margin: 0 !important; max-width: 100% !important;
          }
          [data-testid="stVerticalBlock"] { gap: 0 !important; }
          [data-testid="stElementContainer"] { margin: 0 !important; }
          iframe[title="restaurant_date"] {
            display: block !important; width: 100% !important;
            min-height: 100vh !important; border: 0 !important; margin: 0 !important;
          }
        </style>
        """, unsafe_allow_html=True)
        restaurant_date(key="restaurant_date_scene_v3", height=760, scrolling=False)
